solution:
def stable_group_indices(items):
    result = {}
    for i, value in enumerate(items):
        result.setdefault(value, []).append(i)
    return result

def rotate_grid_clockwise(grid):
    if not grid or not grid[0]:
        return []
    return [list(row) for row in zip(*grid[::-1])]

def compact_runs(values):
    result = []
    for value in values:
        if result and result[-1][0] == value:
            result[-1] = (value, result[-1][1] + 1)
        else:
            result.append((value, 1))
    return result

def reachable_nodes(edges, start):
    adjacency = {}
    for a, b in edges:
        adjacency.setdefault(a, []).append(b)
    seen = {start}
    pending = [start]
    while pending:
        for nxt in adjacency.get(pending.pop(), []):
            if nxt not in seen:
                seen.add(nxt)
                pending.append(nxt)
    return sorted(seen)

def first_peak_plateau(values):
    i = 0
    while i < len(values):
        j = i + 1
        while j < len(values) and values[j] == values[i]:
            j += 1
        if i > 0 and j < len(values) and values[i] > values[i-1] and values[i] > values[j]:
            return i
        i = j
    return -1

