solution:
def bracket_pairs(text):
    stack = []
    result = {}
    for i, ch in enumerate(text):
        if ch == "(":
            stack.append(i)
        elif ch == ")":
            if not stack:
                raise ValueError("unmatched")
            result[stack.pop()] = i
    if stack:
        raise ValueError("unmatched")
    return result

def gap_ranges(nums, low, high):
    if low > high:
        return []
    cursor = low
    result = []
    for value in nums:
        if value < cursor or value > high:
            continue
        if cursor < value:
            result.append((cursor, value - 1))
        cursor = value + 1
    if cursor <= high:
        result.append((cursor, high))
    return result

