solution:
def alternating_chunks(values, width):
    if width <= 0:
        raise ValueError("width")
    result = []
    for index, start in enumerate(range(0, len(values), width)):
        part = values[start:start + width]
        result.extend(part[::-1] if index % 2 else part)
    return result
